SELECT pro.id, pro.code, pro.purchase_order_code, pro.supplier_name, pro.approve_status, pro.invalid_status, prod.sku_id, prod.sku_no, pro.bill_date, pro.return_warehouse_name, prod.reality_return_qty, pro.return_remark, pro.return_mode, pro.purchase_user_id, pro.return_user_name, prod.remark, pro.approve_user_name, pro.create_user_name, pro.create_time FROM purchase_return_order_detail prod LEFT JOIN purchase_return_order pro ON prod.main_id = pro.id AND prod.is_deleted = FALSE WHERE pro.is_deleted = FALSE
and prod.sku_no in
#{item}
and pro.supplier_id in
#{item}
and pro.purchaseOrderCode = #{params.purchaseOrderCode}
and pro.purchase_user_id in
#{item}
and pro.approve_status in
#{item}
and pro.invalidStatus = #{params.invalidStatus}
and pro.return_mode = #{params.returnMode}
and pro.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > wr.create_time
and pro.return_warehouse_id in
#{item}
and pro.create_user_id in
#{item}
and pro.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > wr.create_time
${params.param}
ORDER BY
${item.field} ${item.sort}
pro.create_time,pro.id desc

